// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        // keep the domain wide: any caller except the current owner (address(0)),
        // and any non-zero new owner, must be admissible
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(caller);
        try c.transferOwnership(newOwner) { /* may succeed or revert */ } catch { }

        // invariant: a non-owner can never change the owner
        assertTrue(c.owner() == address(0));
    }
}
